cat <<'EOF' > src/cmd/headers.rs
use csv;
use docopt::Docopt;
use serde::Deserialize;
use std::io;

const USAGE: &'static str = "
Prints the fields of the first row in the CSV data.

These names can be used in commands like 'select' to refer to columns in the
CSV data.

Note that multiple CSV files may be given to this command. This is useful with
the --intersect flag.

Usage:
    xsv headers [options] [<input>...]

headers options:
    -j, --just-names       Only show the header names (hide column index).
                           This is automatically enabled if more than one
                           input is given.
    --intersect            Shows the intersection of all headers in all of
                           the inputs given.

Common options:
    -h, --help             Display this message
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

#[derive(Debug, Deserialize)]
struct Args {
    arg_input: Vec<String>,
    flag_just_names: bool,
    flag_intersect: bool,
    flag_delimiter: Option<char>,
}

pub fn run(argv: &[String]) {
    let args: Args = Docopt::new(USAGE)
        .and_then(|d| d.argv(argv.iter().map(|s| &**s)).deserialize())
        .unwrap_or_else(|e| e.exit());

    let mut all_headers: Vec<Vec<String>> = Vec::new();

    for input in &args.arg_input {
        let mut rdr = csv::ReaderBuilder::new()
            .delimiter(args.flag_delimiter.unwrap_or(',') as u8)
            .from_path(input)
            .expect("Could not open file");

        let headers = rdr.headers().expect("Could not read headers");
        all_headers.push(headers.iter().map(|s| s.to_string()).collect());
    }

    // If no input, read from stdin
    if args.arg_input.is_empty() {
         let mut rdr = csv::ReaderBuilder::new()
            .delimiter(args.flag_delimiter.unwrap_or(',') as u8)
            .from_reader(io::stdin());

        let headers = rdr.headers().expect("Could not read headers");
        all_headers.push(headers.iter().map(|s| s.to_string()).collect());
    }

    if args.flag_intersect {
        // As observed, it seems to be a unique set of all headers in order of appearance
        let mut unique_headers = Vec::new();
        for headers in all_headers {
            for h in headers {
                if !unique_headers.contains(&h) {
                    unique_headers.push(h);
                }
            }
        }
        for h in unique_headers {
            println!("{}", h);
        }
    } else {
        let just_names = args.flag_just_names || all_headers.len() > 1;
        for headers in all_headers {
            for (i, h) in headers.iter().enumerate() {
                if just_names {
                    println!("{}", h);
                } else {
                    println!("{}   {}", i + 1, h);
                }
            }
        }
    }
}
EOF
"}

