use docopt::Docopt;
use serde::Deserialize;
use std::fs::File;
use std::io::{self, Write, BufWriter};

const USAGE: &'static str = "
Create CSV index for faster access.

Usage:
    xsv index [options] <input>

index options:
    -o, --output <file>    Write output to <file> instead of stdout.

Common options:
    -h, --help             Display this message
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

#[derive(Debug, Deserialize)]
struct Args {
    arg_input: String,
    flag_output: Option<String>,
    flag_delimiter: Option<char>,
}

pub fn run(argv: &[String]) {
    let args: Args = Docopt::new(USAGE)
        .and_then(|d| d.argv(argv.iter().map(|s| &**s)).deserialize())
        .unwrap_or_else(|e| e.exit());

    let mut rdr = csv::ReaderBuilder::new()
        .delimiter(args.flag_delimiter.unwrap_or(',') as u8)
        .has_headers(false)
        .from_path(&args.arg_input)
        .expect("Could not open input file");

    let mut offsets = Vec::new();
    let mut pos = csv::Position::new();

    // We need to get the offset of each record.
    // The first record starts at the current position.
    offsets.push(pos.byte());

    let mut count = 0u64;
    let mut byte_rdr = rdr.into_byte_records();
    while let Some(result) = byte_rdr.next() {
        result.expect("Error reading CSV record");
        count += 1;
        // The position AFTER reading a record is the start of the NEXT record.
        offsets.push(byte_rdr.reader().position().byte());
    }
    // The last offset added is the EOF position, we don't want it as a record start.
    offsets.pop();

    let index_path = match args.flag_output {
        Some(path) => path,
        None => format!("{}.idx", args.arg_input),
