    let mut wtr = BufWriter::new(File::create(index_path).expect("Could not create index file"));
    for offset in offsets {
        wtr.write_all(&offset.to_be_bytes()).expect("Could not write offset");
    }
    wtr.write_all(&count.to_be_bytes()).expect("Could not write count");
    wtr.flush().expect("Could not flush index file");
}
