use serde::Deserialize;
use std::io::{self, Read, Seek, SeekFrom};
use std::fs::File;
use std::path::Path;

const USAGE: &'static str = "
Prints a count of the number of records in the CSV data.

Note that the count will not include the header row (unless --no-headers is
given).

Usage:
    xsv count [options] [<input>]

Common options:
    -h, --help             Display this message
    -n, --no-headers       When set, the first row will not be included in
                           the count.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

#[derive(Debug, Deserialize)]
struct Args {
    arg_input: Option<String>,
    flag_no_headers: bool,
    flag_delimiter: Option<char>,
}

pub fn run(argv: &[String]) {
    let args: Args = Docopt::new(USAGE)
        .and_then(|d| d.argv(argv.iter().map(|s| &**s)).deserialize())
        .unwrap_or_else(|e| e.exit());

    let mut count = 0u64;

    if let Some(ref input) = args.arg_input {
        let idx_path = format!("{}.idx", input);
        if Path::new(&idx_path).exists() {
            let mut idx_file = File::open(&idx_path).expect("Could not open index file");
            idx_file.seek(SeekFrom::End(-8)).expect("Could not seek in index file");
            let mut buf = [0u8; 8];
            idx_file.read_exact(&mut buf).expect("Could not read count from index file");
            count = u64::from_be_bytes(buf);
            if !args.flag_no_headers && count > 0 {
                count -= 1;
            }
            println!("{}", count);
            return;
        }
    }

    let mut rdr_builder = csv::ReaderBuilder::new();
    rdr_builder.delimiter(args.flag_delimiter.unwrap_or(',') as u8);
    rdr_builder.has_headers(!args.flag_no_headers);

    match args.arg_input {
        Some(input) => {
            let mut rdr = rdr_builder.from_path(input).expect("Could not open file");
            for _ in rdr.records() {
                count += 1;
            }
        }
        None => {
            let mut rdr = rdr_builder.from_reader(io::stdin());
            for _ in rdr.records() {
                count += 1;
            }
        }
    }
    println!("{}", count);
}
