use csv;
use docopt::Docopt;
use serde::Deserialize;
use std::io;

const USAGE: &'static str = "
Prints flattened records such that fields are labeled separated by a new line.
This mode is particularly useful for viewing one record at a time. Each
record is separated by a special '#' character (on a line by itself), which
can be changed with the --separator flag.

There is also a condensed view (-c or --condense) that will shorten the
contents of each field to provide a summary view.

Usage:
    xsv flatten [options] [<input>]

flatten options:
    -c, --condense <arg>  Limits the length of each field to the value
                           specified. If the field is UTF-8 encoded, then
                           <arg> refers to the number of code points.
                           Otherwise, it refers to the number of bytes.
    -s, --separator <arg>  A string of characters to write after each record.
                           When non-empty, a new line is automatically
                           appended to the separator.
                           [default: #]

Common options:
    -h, --help             Display this message
    -n, --no-headers       When set, the first row will not be interpreted
                           as headers. When set, the name of each field
                           will be its index.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

#[derive(Debug, Deserialize)]
struct Args {
    arg_input: Option<String>,
    flag_condense: Option<usize>,
    flag_separator: String,
    flag_no_headers: bool,
    flag_delimiter: Option<char>,
}

pub fn run(argv: &[String]) {
    let args: Args = Docopt::new(USAGE)
        .and_then(|d| d.argv(argv.iter().map(|s| &**s)).deserialize())
        .unwrap_or_else(|e| e.exit());

    let mut rdr_builder = csv::ReaderBuilder::new();
    rdr_builder.delimiter(args.flag_delimiter.unwrap_or(',') as u8);
    rdr_builder.has_headers(!args.flag_no_headers);

    let mut rdr = match args.arg_input {
        Some(path) => rdr_builder.from_path(path).expect("Could not open input file"),
        None => rdr_builder.from_reader(io::stdin()),
    };

    let headers = if !args.flag_no_headers {
        rdr.headers().expect("Could not read headers").clone()
    } else {
        csv::StringRecord::new()
    };

    let mut first = true;
    for result in rdr.records() {
        if !first {
            if !args.flag_separator.is_empty() {
                println!("{}", args.flag_separator);
            }
        }
        first = false;

        let record = result.expect("Could not read record");
        for (i, field) in record.iter().enumerate() {
            let name = if args.flag_no_headers {
                i.to_string()
            } else {
                headers.get(i).unwrap_or("").to_string()
            };

            let mut value = field.to_string();
            if let Some(limit) = args.flag_condense {
                if value.chars().count() > limit {
                    value = value.chars().take(limit).collect();
                }
            }
            println!("{}  {}", name, value);
        }
    }
}
