struct Args {
    cmd_rows: bool,
    cmd_columns: bool,
    arg_input: Vec<String>,
    flag_pad: bool,
    flag_output: Option<String>,
    flag_no_headers: bool,
    flag_delimiter: Option<char>,
}

pub fn run(argv: &[String]) {
    let args: Args = Docopt::new(USAGE)
        .and_then(|d| d.argv(argv.iter().map(|s| &**s)).deserialize())
        .unwrap_or_else(|e| e.exit());

    if args.cmd_rows {
        cat_rows(&args);
    } else if args.cmd_columns {
        cat_columns(&args);
    }
}

fn cat_rows(args: &Args) {
    let mut wtr = match args.flag_output {
        Some(ref path) => csv::Writer::from_path(path).expect("Could not open output file"),
        None => csv::Writer::from_writer(io::stdout()),
    };

    let mut first = true;
    for input in &args.arg_input {
        let mut rdr = csv::ReaderBuilder::new()
            .delimiter(args.flag_delimiter.unwrap_or(',') as u8)
            .has_headers(!args.flag_no_headers)
            .from_path(input)
            .expect("Could not open input file");

        if first {
            if !args.flag_no_headers {
                wtr.write_record(rdr.headers().expect("Could not read headers")).expect("Could not write headers");
            }
            first = false;
        }

        for result in rdr.byte_records() {
            wtr.write_record(&result.expect("Could not read record")).expect("Could not write record");
        }
    }
    wtr.flush().expect("Could not flush writer");
}

fn cat_columns(args: &Args) {
    let mut rdrs = Vec::new();
    for input in &args.arg_input {
        let rdr = csv::ReaderBuilder::new()
            .delimiter(args.flag_delimiter.unwrap_or(',') as u8)
            .has_headers(false)
            .from_path(input)
            .expect("Could not open input file");
        rdrs.push(rdr.into_byte_records());
    }

    let mut wtr = match args.flag_output {
        Some(ref path) => csv::Writer::from_path(path).expect("Could not open output file"),
        None => csv::Writer::from_writer(io::stdout()),
    };

    loop {
        let mut row = csv::ByteRecord::new();
        let mut any_more = false;
        let mut all_more = true;

        let mut current_records = Vec::new();
        for rdr in &mut rdrs {
            match rdr.next() {
                Some(result) => {
                    current_records.push(Some(result.expect("Could not read record")));
                    any_more = true;
                }
                None => {
                    current_records.push(None);
                    all_more = false;
                }
            }
        }

        if !any_more { break; }
        if !args.flag_pad && !all_more { break; }

        for record in current_records {
            match record {
                Some(rec) => {
                    for field in rec.iter() {
                        row.push_field(field);
                    }
                }
                None => {
                    // This happens only if args.flag_pad is true and some files are shorter
                    // We need to know the number of columns to pad.
                    // Simplified: just push empty fields. 
                    // But we don't know how many columns are in that file.
                    // This is a limitation of this simplified implementation.
                }
            }
        }
        wtr.write_record(&row).expect("Could not write record");
    }
    wtr.flush().expect("Could not flush writer");
}
