        let record = result.expect("Could not read record");
        let mut new_record = csv::StringRecord::new();
        for &i in &indices {
            new_record.push_field(record.get(i).unwrap_or(""));
        }
        wtr.write_record(&new_record).expect("Could not write record");
    }
    wtr.flush().expect("Could not flush writer");
}
